async function cleanupDemoSessions(db, demo) {
  if (!runtimeNamespace().startsWith("_specialized_preview_"))
    throw Error("Preview only");
  const users = new Set(demo.userIds);
  if ([...users].some((u) => !u.startsWith(demo.id + "-")))
    throw Error("Invalid DEMO ownership");
  const exams = (db.assessments || []).filter(
    (a) => a.institutionId === demo.schoolId && users.has(a.teacherId)
  );
  const examIds = new Set(exams.map((a) => a.id));
  if (["attempts", "examSessions"].some(
    (name) => (db[name] || []).some(
      (s) => examIds.has(s.assessmentId) && !users.has(s.studentId)
    )
  ))
    throw Error("A non-DEMO legacy participant requires separate review");
  const store2 = examSessionStore(), keys = [];
  for (const exam of exams) {
    let after;
    do {
      const rows = await store2.list(demo.schoolId, exam.id, after);
      if (rows.some((r) => !users.has(r.session.studentId)))
        throw Error("A non-DEMO learner session requires separate review");
      keys.push(...rows.map((r) => r.key));
      after = rows.length === 50 ? rows.at(-1).key : void 0;
    } while (after);
  }
  for (const key of keys) await store2.deleteFixture(key);
  return keys.length;
}

// src/server/cleanupDemoExams.ts
function cleanupDemoExams(db, schoolId, users) {
  const exams = new Set((db.assessments || []).filter((a) => a.institutionId === schoolId && users.has(a.teacherId)).map((a) => a.id));
  if (["attempts", "examSessions"].some((name) => (db[name] || []).some((r) => exams.has(r.assessmentId) && !users.has(r.studentId)))) return false;
  const questions = new Set((db.assessments || []).filter((a) => exams.has(a.id)).flatMap((a) => a.questionIds || []));
  const attempts = new Set((db.attempts || []).filter((a) => a.institutionId === schoolId && (users.has(a.studentId) || exams.has(a.assessmentId))).map((a) => a.id));
  db.assessments = (db.assessments || []).filter((a) => !exams.has(a.id));
  db.questions = (db.questions || []).filter((q) => !questions.has(q.id));
  for (const name of ["attempts", "examSessions", "assignments", "gradingRecords"]) db[name] = (db[name] || []).filter((r) => r.institutionId !== schoolId || !(exams.has(r.assessmentId) || attempts.has(r.attemptId) || users.has(r.studentId)));
  return true;
}

