    if (mapping.fullNameCol) score += 3;
    if (mapping.firstNameCol) score += 2;
    if (mapping.lastNameCol) score += 2;
    if (mapping.studentIdCol) score += 2;
    if (mapping.emailCol) score += 2;
    if (mapping.patronymicCol) score += 1;
